import {rooms,items,priorities,merchants,products,searchUrl} from './data.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bed:'M3 18v3 M21 18v3 M3 10V5h18v5 M2 18v-6a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v6z M6 10V7h5v3 M13 10V7h5v3',bath:'M3 12h18v3a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5z M5 12V5a2 2 0 0 1 4 0 M7 20v2 M17 20v2',cup:'M4 8h12v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4z M16 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M12 2v3',sofa:'M5 11V7a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v4 M5 14h14 M5 11H2v8h20v-8h-3v5H5z M5 19v2 M19 19v2',desk:'M3 10h18v3H3z M5 13v8 M19 13v8 M7 10V3h10v7 M12 13v3',basket:'M3 8h18l-2 13H5z M7 8l3-6 M17 8l-3-6 M8 12v5 M12 12v5 M16 12v5',upload:'M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6',check:'M5 12l4 4L20 5'};
export const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
let saved={};try{saved=JSON.parse(localStorage.getItem('settlein-v1')||'{}')||{}}catch{}
const state={done:new Set(Array.isArray(saved.done)?saved.done.filter(id=>items.some(i=>i.id===id)):[]),budget:Number.isFinite(saved.budget)&&saved.budget>=100?saved.budget:1500,style:['balanced','save','comfort'].includes(saved.style)?saved.style:'balanced',room:'all',mode:'general',priority:'all',store:'all',unfinished:false,collapsed:new Set(),roomPlans:saved.roomPlans&&typeof saved.roomPlans==='object'?saved.roomPlans:{}};
function persist(){try{localStorage.setItem('settlein-v1',JSON.stringify({done:[...state.done],budget:state.budget,style:state.style,roomPlans:state.roomPlans}));}catch{toast('This browser cannot save your changes. They may be lost when you close the tab.')}}
let toastTimer;export function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
function currentItems(){return items.filter(i=>(state.room==='all'||state.room===i.room)&&(state.priority==='all'||state.priority===i.priority)&&(!state.unfinished||!state.done.has(i.id)))}
function estimate(i){const factor=state.style==='save'?.75:state.style==='comfort'?1.4:1;return Math.round(i.estimate*factor)}
function nav(){const active=state.room;$('#room-nav').innerHTML=rooms.map(r=>`<a class="nav-item ${active===r.id?'active':''}" href="#${state.mode}/${r.id}" ${active===r.id?'aria-current="page"':''} title="${r.name}">${icon(r.icon)}<span>${r.name}</span><span class="nav-count">${r.id==='all'?items.length:items.filter(i=>i.room===r.id).length}</span></a>`).join('')}
function renderChecklist(){const list=currentItems();const room=rooms.find(r=>r.id===state.room);$('#room-title').textContent=state.room==='all'?'Your move-in checklist':`${room.name} checklist`;$('#room-description').textContent=room.description;$('#room-count').textContent=`${list.length} items`;
$('#checklist').innerHTML=list.length?rooms.filter(r=>r.id!=='all'&&list.some(i=>i.room===r.id)).map(r=>{const rows=list.filter(i=>i.room===r.id);const all=items.filter(i=>i.room===r.id);const collapsed=state.collapsed.has(r.id);return `<section class="check-group"><button class="group-title" data-collapse="${r.id}" aria-expanded="${!collapsed}" aria-controls="group-${r.id}">${icon(r.icon)}<strong>${r.name}</strong><small>${r.en}</small><span class="group-progress">${all.filter(i=>state.done.has(i.id)).length} / ${all.length}</span><span class="chevron" aria-hidden="true">${collapsed?'+':'−'}</span></button><div class="group-items" id="group-${r.id}" ${collapsed?'hidden':''}>${rows.map(i=>`<div class="check-row ${state.done.has(i.id)?'done':''}"><input type="checkbox" data-check="${i.id}" aria-label="${i.name} ready" ${state.done.has(i.id)?'checked':''}><div class="item-text"><div class="item-title"><span>${i.name}</span><span class="priority-tag ${i.priority}">${priorities[i.priority]}</span></div><p>${i.note}</p></div><div class="item-estimate">${money(estimate(i))}<small>Allowance</small></div><button class="shop-item" data-shop="${i.id}" aria-label="Find ${i.name} products">Shop picks ↗</button></div>`).join('')}</div></section>`}).join(''):'<div class="empty">No items left for these filters.<br><button id="reset-filters">Show all items</button></div>';
document.querySelectorAll('[data-collapse]').forEach(b=>b.onclick=()=>{state.collapsed.has(b.dataset.collapse)?state.collapsed.delete(b.dataset.collapse):state.collapsed.add(b.dataset.collapse);renderChecklist()});
document.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>setDone(c.dataset.check,c.checked));document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>itemDialog(b.dataset.shop));if($('#reset-filters'))$('#reset-filters').onclick=()=>{state.priority='all';state.unfinished=false;$('#unfinished').checked=false;filterActive();renderChecklist()};}
function setDone(id,done){if(!items.some(i=>i.id===id)||typeof done!=='boolean')throw Error('Invalid checklist item');done?state.done.add(id):state.done.delete(id);persist();const focus=document.activeElement?.dataset.check;renderChecklist();renderSummary();if(focus)document.querySelector(`[data-check="${focus}"]`)?.focus();return {id,done,completed:state.done.size,total:items.length}}
function renderSummary(){const total=items.length,done=state.done.size,arrival=items.filter(i=>i.priority==='arrival'),ready=arrival.filter(i=>state.done.has(i.id)).length;$('#progress-panel').innerHTML=`<section class="progress-card"><div class="progress-header"><h3>Settling-in progress</h3><span>${Math.round(done/total*100)}% READY</span></div><div class="progress-number">${done}<small> / ${total} items ready</small></div><div class="progress-track" role="progressbar" aria-label="Shopping progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><span style="width:${done/total*100}%"></span></div><p>${ready===arrival.length?'Your arrival essentials are ready!':`Arrival essentials ready: ${ready} / ${arrival.length} items`}</p></section>`;
const planned=items.reduce((s,i)=>s+estimate(i),0),remaining=items.filter(i=>!state.done.has(i.id)).reduce((s,i)=>s+estimate(i),0);const first=items.filter(i=>i.priority==='arrival'&&!state.done.has(i.id)).reduce((s,i)=>s+estimate(i),0);$('#budget-summary').innerHTML=`<div class="budget-breakdown"><div class="budget-line"><span>Full list estimate</span><strong>${money(planned)}</strong></div><div class="budget-line"><span>Still to get</span><strong>${money(remaining)}</strong></div><div class="budget-line"><span>Arrival essentials</span><strong>${money(first)}</strong></div></div><div class="budget-alert ${remaining>state.budget?'over':''}">${remaining>state.budget?`Your remaining list is over budget by ${money(remaining-state.budget)}. Start with essentials and measure before buying furniture.`:`Your remaining list leaves ${money(state.budget-remaining)} for tax, shipping and unexpected needs.`}</div>`;}
function renderProducts(){const candidate=products.filter(p=>(state.room==='all'||p.room===state.room)&&(state.store==='all'||p.store===state.store));const shown=state.room==='all'&&state.store==='all'?candidate.slice(0,6):candidate;$('#store-filters').innerHTML=['all',...merchants].map(s=>`<button data-store="${s}" class="${s===state.store?'active':''}">${s==='all'?'All retailers':s}</button>`).join('');$('#products').innerHTML=shown.length?shown.map(p=>`<article class="product-card"><div class="product-media"><span class="product-badge">${p.badge}</span>${p.image?`<img src="${p.image}" alt="${p.name}" loading="lazy">`:`<div class="product-type">${icon(rooms.find(r=>r.id===p.room).icon)}${p.store} picks</div>`}</div><div class="product-body"><span class="merchant">${p.store.toUpperCase()}</span><h3>${p.name}</h3><p>${p.subtitle}</p><div class="product-price">${p.price===null?'Check price':`$${p.price.toFixed(2)}`}<small>${p.price===null?'at retailer':'Reference price'}</small></div><button data-product="${p.id}">Why this pick ↗</button></div></article>`).join(''):`<div class="empty" style="grid-column:1/-1">No verified picks for this selection yet.<br>Use Shop picks in the checklist to search all four retailers.</div>`;document.querySelectorAll('[data-store]').forEach(b=>b.onclick=()=>{state.store=b.dataset.store;renderProducts()});document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>productDialog(b.dataset.product));document.querySelectorAll('.product-media img').forEach(img=>img.onerror=()=>{img.replaceWith(Object.assign(document.createElement('span'),{className:'product-type',textContent:'Product image unavailable'}))})}
function showDialog(html){$('#product-detail').innerHTML=html;$('#product-dialog').showModal()}
function itemDialog(id){const i=items.find(i=>i.id===id),recs=products.filter(p=>p.item===id);showDialog(`<div class="detail-label">${rooms.find(r=>r.id===i.room).en.toUpperCase()} / ${priorities[i.priority]}</div><h2>${i.name}</h2><p>${i.note}</p><div class="detail-block"><h3>Choose your specs, then your store</h3><p>Planning allowance: ${money(estimate(i))}. These retailer search links let you compare size, material and delivery options. They are not live price comparisons.</p></div>${recs.length?`<div class="detail-block"><h3>Sourced picks</h3>${recs.map(p=>`<p><a href="${p.url}" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">${p.store} · ${p.name} ↗</a></p><p>${p.reason}</p>`).join('')}</div>`:''}<div class="store-links">${merchants.map((s,k)=>`<a class="${k?'secondary':''}" href="${searchUrl(s,i.query)}" target="_blank" rel="noopener noreferrer">Search ${s} ↗</a>`).join('')}</div>`)}
function productDialog(id){const p=products.find(p=>p.id===id);showDialog(`<div class="detail-label">${p.store.toUpperCase()} / ${p.badge}</div><h2>${p.name}</h2><p>${p.subtitle}</p><div class="detail-block"><h3>Why this pick</h3><p>${p.reason}</p></div><div class="detail-block"><h3>Before you order</h3><p>${p.caution}</p></div><p>${p.price===null?'Check the current price on the product page. ':`Reference price $${p.price.toFixed(2)}, excluding tax, shipping and assembly. `}Checked September 17, 2026.</p><a class="detail-primary" href="${p.url}" target="_blank" rel="noopener noreferrer">Visit ${p.store} — view product ↗</a>`)}
function filterActive(){document.querySelectorAll('[data-priority]').forEach(b=>{b.classList.toggle('active',b.dataset.priority===state.priority);b.setAttribute('aria-pressed',String(b.dataset.priority===state.priority))})}
let plannerModule;
async function route(){const [rawMode,rawRoom]=(location.hash.slice(1)||'general/all').split('/');state.mode=rawMode==='customize'?'customize':'general';state.room=rooms.some(r=>r.id===rawRoom)?rawRoom:'all';if(state.mode==='customize'&&state.room==='all')state.room='bedroom';nav();$('#general-view').hidden=state.mode!=='general';$('#customize-view').hidden=state.mode!=='customize';$('#general-tab').setAttribute('aria-selected',String(state.mode==='general'));$('#customize-tab').setAttribute('aria-selected',String(state.mode==='customize'));$('#breadcrumb').textContent=state.mode==='general'?'Shopping planner':'Your space';if(state.mode==='general'){renderChecklist();renderProducts();renderSummary()}else{plannerModule??=await import('./planner.js');plannerModule.renderPlanner($('#customize-view'),state,{persist,toast,esc,icon,searchUrl,rooms,products})}}
document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{state.priority=b.dataset.priority;filterActive();renderChecklist()});$('#unfinished').onchange=e=>{state.unfinished=e.target.checked;renderChecklist()};$('#budget').value=state.budget;$('#budget-style').value=state.style;$('#budget').onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||n<100||n>50000){e.target.value=state.budget;toast('Enter a budget between $100 and $50,000.');return}state.budget=n;persist();renderSummary()};$('#budget-style').onchange=e=>{state.style=e.target.value;persist();renderChecklist();renderSummary()};$('.dialog-close').onclick=()=>$('#product-dialog').close();$('#product-dialog').addEventListener('click',e=>{if(e.target===$('#product-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('.welcome-photo img').onerror=()=>{document.querySelector('.welcome').classList.add('image-failed')};window.addEventListener('hashchange',route);filterActive();route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_checklist_items',title:'Update checklist',description:'Mark checklist items as ready or not ready and save them in this browser.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string'},done:{type:'boolean'}},required:['id','done'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.items)||input.items.some(v=>!v||typeof v.done!=='boolean'||!items.some(i=>i.id===v.id)))throw Error('Provide valid item IDs and boolean values');return {results:input.items.map(v=>setDone(v.id,v.done))}}})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'get_checklist',title:'Read checklist',description:'Read checklist items and their saved completion state in this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {items:items.map(i=>({id:i.id,name:i.name,room:i.room,done:state.done.has(i.id)}))}}})).catch(()=>{})}catch{}}
